'use strict';
// Only the class main stat contributes to ATK, one point per stat.
const CLASS_STATS={warrior:{main:'str'},mage:{main:'int'},archer:{main:'dex'},thief:{main:'luk'},inventor:{main:'dex'}};
const STAT_NAMES={str:'STR',dex:'DEX',int:'INT',luk:'LUK'};
let inventoryCategory='equipment',characterResume=false;
function statProfile(job=player.job){const family=job==='mage'?'mage':job==='archer'?'archer':job==='thief'?'thief':job==='inventor'?'inventor':'warrior';return CLASS_STATS[family]}
function validateSpecial(raw){const out={ignoreDef:0,damage:0,bossDamage:0,criDamage:0};if(raw===undefined)return out;if(!raw||typeof raw!=='object')throw Error('พลังพิเศษไม่ถูกต้อง');for(const key of Object.keys(out)){if(raw[key]!==undefined){if(typeof raw[key]!=='number'||!Number.isFinite(raw[key])||raw[key]<0)throw Error('พลังพิเศษไม่ถูกต้อง');out[key]=Math.min(key==='ignoreDef'?100:1000,raw[key])}}return out}
function equippedItems(job=player.job,p=player){const defaults=[{slot:'main',label:'อาวุธหลัก',item:job==='spearman'?'หอกฝึก':job==='greatsword'?'ดาบใหญ่ฝึก':'ดาบฝึกมือเดียว',icon:job==='spearman'?'spear':'sword',atk:17,description:'ATK 17 · อาวุธเริ่มต้น'},{slot:'secondary',label:'อาวุธรอง',item:['greatsword','spearman'].includes(job)?null:'โล่ไม้',icon:'shield',def:3,description:'DEF 3 · โล่เริ่มต้น'},{slot:'accessory1',label:'ประดับ 1'},{slot:'accessory2',label:'ประดับ 2'},{slot:'hat',label:'หมวก'},{slot:'shirt',label:'เสื้อ'},{slot:'gloves',label:'ถุงมือ'},{slot:'shoes',label:'รองเท้า'}];return defaults.map(base=>{const gear=p.loot?.gear.find(g=>g.id===p.loot.equipped[base.slot]);return gear?{...base,...gear,item:gear.name,description:gearDescription(gear),icon:gear.slot==='main'?'sword':gear.slot==='secondary'?'shield':gear.slot}:base})}
function characterStatus(p=player){
 const second=secondBonuses(p);p={...p,str:p.str+second.str,dex:p.dex+second.dex};
 const equipped=equippedItems(p.job,p),bonus={};for(const gear of equipped)for(const b of gear.bonuses||[])bonus[b.key]=(bonus[b.key]||0)+b.value;p={...p};for(const key of ['str','dex','int','luk'])p[key]=(p[key]||0)+(bonus[key]||0);
 const family=statProfile(p.job),main=p[family.main]||0,level=p.level||1,luk=p.luk??5;
 const items=equipped,weaponATK=items.reduce((n,i)=>n+(i.item?i.atk||0:0),0),gearDEF=items.reduce((n,i)=>n+(i.item?i.def||0:0),0);
 const special=p.special||{ignoreDef:0,damage:0,bossDamage:0};
 const result={hp:Math.round((90+p.str*10+(level-1)*12)*(1+(p.swordSkills?.warriorMastery||0)*.01+(p.swordSkills?.ironBody||0)*.02)),mp:40+p.int*10+(level-1)*5,atk:Math.max(1,Math.round(weaponATK+main)),def:gearDEF+p.str+(JOBS[p.job]?.defense||0)+(p.swordSkills?.ironBody||0),cri:Math.min(100,(luk+p.dex)*.125),criDamage:150+(special.criDamage||0),acc:90+p.dex+p.int,avoid:Math.min(100,luk*.125),ignoreDef:special.ignoreDef||0,damage:special.damage||0,bossDamage:special.bossDamage||0};for(const key of Object.keys(result))result[key]+=(bonus[key]||0);result.hp+=items.reduce((n,g)=>n+(g.hp||0),0);result.mp+=items.reduce((n,g)=>n+(g.mp||0),0);result.cri=Math.min(100,result.cri);result.avoid=Math.min(100,result.avoid);result.ignoreDef=Math.min(100,result.ignoreDef);result.atk=Math.round((result.atk+second.atk)*second.damageFactor);result.def+=second.def;result.hp=Math.round(result.hp*second.hpFactor);result.mp=Math.round(result.mp*second.mpFactor);return result;
}
function itemIcon(type){const shapes={sword:'<path d="M20 4 8 16l-2-2L18 2Z" fill="#dfebce" stroke="#708b7e"/><path d="m5 13 6 6M7 17l-4 4" stroke="#d9b76e" stroke-width="3"/>',shield:'<path d="M5 4h14v10l-7 8-7-8Z" fill="#aa9262" stroke="#dcbd78" stroke-width="2"/><path d="M12 5v14M6 11h12" stroke="#546d55" stroke-width="2"/>',spear:'<path d="m16 2 5 3-7 6Z" fill="#e0eacf" stroke="#718576"/><path d="M16 6 3 22" stroke="#bd9e63" stroke-width="3"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(shapes[type]||'')+'</svg>'}
function renderInventory(category=inventoryCategory){hideUpgradeTooltip();inventoryCategory=category;document.querySelectorAll('[data-inventory]').forEach(b=>{const selected=b.dataset.inventory===category;b.setAttribute('aria-selected',String(selected));b.classList.toggle('selected',selected)});$('inventoryGrid').setAttribute('aria-labelledby','tab-'+category);$('inventoryGrid').replaceChildren();const items=category==='usable'?Object.entries(POTION_ITEMS).filter(([id])=>player.consumables[id]>0):[];const extras=category==='usable'?boxStacks().concat(player.promotionTokens?[{type:'promotionToken',name:'ตรานักรบ'}]:[]):bagEquipment();for(let i=0;i<Math.max(20,items.length+extras.length);i++){const cell=document.createElement(items[i]?'button':'div');cell.className='inventory-cell';if(items[i]){const [id,item]=items[i],count=player.consumables[id];cell.classList.add('inventory-item',item.kind+'-potion');cell.setAttribute('aria-label',item.name+' · '+count+' ขวด');const bottle=document.createElement('span');bottle.className='potion-bottle';const amount=document.createElement('strong');amount.className='item-count';amount.textContent=count;cell.append(bottle,amount);cell.onmouseenter=()=>showItemDetail(cell,item,count);cell.onmouseleave=()=>hideUpgradeTooltip(false);cell.onfocus=()=>showItemDetail(cell,item,count);cell.onclick=()=>showItemDetail(cell,item,count,true)}else if(extras[i-items.length]){const data=extras[i-items.length],button=document.createElement('button');button.className='inventory-cell inventory-item';if(data.type==='promotionToken'){button.innerHTML=promotionTokenIcon();button.setAttribute('aria-label','ตรานักรบ · เปลี่ยนอาชีพ');attachLootDetail(button,{name:'ตรานักรบ',description:'ไอเทมพิเศษจากราชาสไลม์ · คลิกเลือกอาชีพขั้น 2'});button.onclick=openPromotionChoices}else if(data.type){button.classList.add('loot-box');button.innerHTML=boxIcon(data.type);const amount=document.createElement('strong');amount.className='item-count';amount.textContent=data.count;button.append(amount);appendBoxLevel(button,data.type);button.setAttribute('aria-label',data.name+' · '+amount.textContent);attachLootDetail(button,{name:data.name,description:boxDescription(data.type)+'\nคลิกเลือกจำนวน · ดับเบิลคลิกเปิด 1 กล่อง'});bindBoxOpening(button,data.type)}else{button.style.color=LOOT_RARITIES[data.rarity].color;button.style.borderColor=LOOT_RARITIES[data.rarity].color;button.innerHTML=gearIcon(data);button.setAttribute('aria-label',data.name+' · '+LOOT_RARITIES[data.rarity].name);attachLootDetail(button,{name:data.name,description:gearDescription(data)});button.onclick=()=>showGearDialog(data)}$('inventoryGrid').append(button);continue}else cell.setAttribute('aria-label','ช่อง '+(i+1)+' ว่าง');$('inventoryGrid').append(cell)}$('inventoryHint').textContent=''}
function renderCharacterWindow(){
 const stats=characterStatus(),profile=statProfile();$('moneyAmount').textContent=player.loot.money.toLocaleString();$('characterIdentity').textContent=player.name+' · '+JOBS[player.job].name+' · Lv. '+player.level;
 $('baseStatGrid').replaceChildren();for(const key of ['str','int','dex','luk']){const row=document.createElement('div');row.className='base-stat'+(key===profile.main?' primary-stat':'');const label=document.createElement('span');label.textContent=STAT_NAMES[key];const value=document.createElement('strong');const gearBonus=equippedItems().reduce((sum,g)=>sum+(g.bonuses||[]).filter(b=>b.key===key).reduce((n,b)=>n+b.value,0),0);value.textContent=player[key]+gearBonus;if(gearBonus){const extra=document.createElement('small');extra.className='stat-gear-bonus';extra.textContent=' (+'+gearBonus+')';value.append(extra)}const plus=document.createElement('button');plus.type='button';plus.className='stat-plus';plus.textContent='+';plus.setAttribute('aria-label','เพิ่ม '+STAT_NAMES[key]);plus.disabled=player.ap<1||player[key]>=999;plus.onclick=e=>{e.stopPropagation();spendAP(key)};row.onmouseenter=()=>showStatPreview(key,row);row.onmouseleave=()=>hideUpgradeTooltip(false);row.onclick=()=>showStatPreview(key,row,true);plus.onfocus=()=>showStatPreview(key,row);row.append(label,value,plus);$('baseStatGrid').append(row)}
 $('mainStatHint').textContent='พลังหลัก '+STAT_NAMES[profile.main]+' · พลังรอง '+STAT_NAMES[profile.secondary];
 function values(id,rows){$(id).replaceChildren();for(const [label,value,percent]of rows){const row=document.createElement('div');const name=document.createElement('span');name.textContent=label;const amount=document.createElement('strong');amount.textContent=value.toLocaleString('en-US',{maximumFractionDigits:3})+(percent?'%':'');row.append(name,amount);$(id).append(row)}}
 values('statusValues',[['HP',stats.hp],['MP',stats.mp],['ATK',stats.atk],['DEF',stats.def],['CRI',stats.cri,true],['CRI.DAMAGE',stats.criDamage,true],['ACC',stats.acc],['AVOID',stats.avoid,true]]);
 values('specialValues',[['IGNORE.DEF',stats.ignoreDef,true],['DAMAGE',stats.damage,true],['BOSS.DAMAGE',stats.bossDamage,true]]);
 $('characterAP').textContent='AP '+player.ap;$('characterJob').textContent=JOBS[player.job].name;
 $('equipmentSlots').replaceChildren();for(const gear of equippedItems()){const cell=document.createElement('button');cell.type='button';cell.className='equipment-slot'+(gear.item?' occupied':'');cell.setAttribute('aria-label',gear.label+' · '+(gear.item||'ว่าง'));if(gear.item){cell.onmouseenter=()=>showItemDetail(cell,gear);cell.onmouseleave=()=>hideUpgradeTooltip(false);cell.onfocus=()=>showItemDetail(cell,gear)}const label=document.createElement('span');label.textContent=gear.label;cell.append(label);if(gear.item){const icon=document.createElement('div');icon.className='gear-icon';icon.innerHTML=gear.id?gearIcon(gear):itemIcon(gear.icon);if(gear.rarity){cell.style.borderColor=LOOT_RARITIES[gear.rarity].color;icon.style.color=LOOT_RARITIES[gear.rarity].color}cell.append(icon)}else{const empty=document.createElement('span');empty.className='empty-gear';empty.textContent='—';cell.append(empty)}cell.onclick=()=>{if(gear.item)showItemDetail(cell,gear,undefined,true);$('equipmentInfo').textContent=gear.item?gear.label+' · '+gear.item+' · '+gear.description:gear.label+' · ช่องว่าง';document.querySelectorAll('.equipment-slot').forEach(b=>b.classList.toggle('selected',b===cell))};$('equipmentSlots').append(cell)}
 $('equipmentInfo').textContent='เลือกช่องเพื่อดูของสวมใส่';renderInventory();
}
function openCharacterWindow(category){if(screen!=='play'||!$('modal').hidden||run?.finished)return;if(category)inventoryCategory=category;characterResume=!paused;paused=true;keys={};toastTimer=0;$('toast').classList.remove('show');renderCharacterWindow();$('characterOverlay').hidden=false;$('closeCharacterBtn').focus();save()}
function closeCharacterWindow(){hideUpgradeTooltip();if($('characterOverlay').hidden)return;$('characterOverlay').hidden=true;keys={};paused=screen!=='play'||!!run?.finished||!$('modal').hidden||!characterResume;if(!paused)canvas.focus({preventScroll:true})}
function toggleCharacterWindow(){if($('characterOverlay').hidden)openCharacterWindow();else closeCharacterWindow()}
window.addEventListener('DOMContentLoaded',()=>{$('closeCharacterBtn').onclick=closeCharacterWindow;$('statusBtn').onclick=()=>openCharacterWindow();for(const b of document.querySelectorAll('[data-inventory]'))b.onclick=()=>renderInventory(b.dataset.inventory)});

function spendAP(key){if(!['str','dex','int','luk'].includes(key)||$('characterOverlay').hidden||player.ap<1||player[key]>=999)return;player[key]++;player.ap--;save();renderCharacterWindow();updateUI();document.querySelector('[aria-label="เพิ่ม '+STAT_NAMES[key]+'"]').focus()}
